CREATE FUNCTION qf.consumer_canonical(v jsonb) RETURNS text LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE result text; n numeric;
BEGIN
 CASE jsonb_typeof(v)
 WHEN 'object' THEN
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(v) k WHERE k IN ('__proto__','prototype','constructor')) THEN RAISE EXCEPTION 'CONSUMER_JSON_KEY'; END IF;
  SELECT '{'||coalesce(string_agg(to_jsonb(key)::text||':'||qf.consumer_canonical(value),',' ORDER BY key COLLATE "C"),'')||'}' INTO result FROM jsonb_each(v);
 WHEN 'array' THEN SELECT '['||coalesce(string_agg(qf.consumer_canonical(value),',' ORDER BY ordinal),'')||']' INTO result FROM jsonb_array_elements(v) WITH ORDINALITY AS a(value,ordinal);
 WHEN 'number' THEN n:=(v::text)::numeric; IF n<>trunc(n) OR abs(n)>9007199254740991 THEN RAISE EXCEPTION 'CONSUMER_JSON_NUMBER'; END IF; result:=(n::bigint)::text;
 ELSE result:=v::text;
 END CASE;
 RETURN result;
END $$;

-- Closed, bounded structural validator. Fixed reviewed rules are supplied only by consumer_schema.
CREATE FUNCTION qf.consumer_json_valid(v jsonb,s jsonb,d integer) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE x jsonb; k text; typ text; str text; units integer; matches integer:=0;
BEGIN
 IF d>32 OR s IS NULL THEN RETURN false; END IF;
 IF s ? 'allOf' THEN FOR x IN SELECT value FROM jsonb_array_elements(s->'allOf') LOOP IF qf.consumer_json_valid(v,x,d) IS NOT TRUE THEN RETURN false; END IF; END LOOP; END IF;
 IF s ? 'anyOf' OR s ? 'oneOf' THEN
  FOR x IN SELECT value FROM jsonb_array_elements(coalesce(s->'anyOf',s->'oneOf')) LOOP IF qf.consumer_json_valid(v,x,d) THEN matches:=matches+1; END IF; END LOOP;
  IF matches=0 OR (s ? 'oneOf' AND matches<>1) THEN RETURN false; END IF;
 END IF;
 IF s ? 'const' AND v IS DISTINCT FROM s->'const' THEN RETURN false; END IF;
 IF s ? 'enum' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'enum') e WHERE e=v) THEN RETURN false; END IF;
 typ:=s->>'type';
 IF typ IS NOT NULL AND NOT (jsonb_typeof(v)=typ OR (typ='integer' AND jsonb_typeof(v)='number' AND (v::text)::numeric=trunc((v::text)::numeric))) THEN RETURN false; END IF;
 CASE jsonb_typeof(v)
 WHEN 'object' THEN
  IF s->'additionalProperties'='false'::jsonb AND EXISTS(SELECT 1 FROM jsonb_object_keys(v) a WHERE NOT coalesce(s->'properties','{}'::jsonb) ? a) THEN RETURN false; END IF;
  IF s ? 'required' AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(s->'required') a WHERE NOT v ? a) THEN RETURN false; END IF;
  FOR k,x IN SELECT key,value FROM jsonb_each(v) LOOP IF s->'properties' ? k AND qf.consumer_json_valid(x,s->'properties'->k,d+1) IS NOT TRUE THEN RETURN false; END IF; END LOOP;
 WHEN 'array' THEN
  IF jsonb_array_length(v)<coalesce((s->>'minItems')::integer,0) OR jsonb_array_length(v)>coalesce((s->>'maxItems')::integer,10000) THEN RETURN false; END IF;
  IF s ? 'items' THEN FOR x IN SELECT value FROM jsonb_array_elements(v) LOOP IF qf.consumer_json_valid(x,s->'items',d+1) IS NOT TRUE THEN RETURN false; END IF; END LOOP; END IF;
 WHEN 'string' THEN
  str:=v#>>'{}'; SELECT length(str)+count(*) FILTER(WHERE ascii(c)>65535)::integer INTO units FROM regexp_split_to_table(str,'') c;
  IF units<coalesce((s->>'minLength')::integer,0) OR units>coalesce((s->>'maxLength')::integer,524288) THEN RETURN false; END IF;
  IF s ? 'pattern' AND str !~ (s->>'pattern') THEN RETURN false; END IF;
 WHEN 'number' THEN IF (s ? 'minimum' AND (v::text)::numeric<(s->>'minimum')::numeric) OR (s ? 'maximum' AND (v::text)::numeric>(s->>'maximum')::numeric) THEN RETURN false; END IF;
 ELSE NULL;
 END CASE;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
CREATE FUNCTION qf.consumer_body_valid(t text,kind text,maximum integer) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE v jsonb;
BEGIN
 IF octet_length(t)<2 OR octet_length(t)>maximum THEN RETURN false; END IF;
 v:=t::jsonb;
 IF qf.consumer_json_valid(v,qf.consumer_schema(kind),0) IS NOT TRUE THEN RETURN false; END IF;
 RETURN (t=qf.consumer_canonical(v)) IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
CREATE FUNCTION qf.consumer_moment(t timestamptz) RETURNS text LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
 SELECT CASE WHEN isfinite(t) AND date_trunc('milliseconds',t)=t AND t>='0001-01-01 00:00:00+00'::timestamptz AND t<'10000-01-01 00:00:00+00'::timestamptz THEN to_char(t AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') ELSE NULL END
$$;

ALTER TABLE qf.product_version ADD CONSTRAINT product_version_parent_exact UNIQUE(id,product_id,snapshot_sha256);
CREATE TABLE qf.internal_play_version (
 id uuid PRIMARY KEY,product_id varchar(80) NOT NULL,slot integer NOT NULL CHECK(slot BETWEEN 1 AND 100),
 parent_version_id uuid NOT NULL,parent_snapshot_sha256 char(64) NOT NULL,operation_key uuid NOT NULL,
 binding_text text NOT NULL,binding_sha256 char(64) NOT NULL CHECK(binding_sha256 ~ '^[a-f0-9]{64}$'),
 snapshot_text text NOT NULL,snapshot_sha256 char(64) NOT NULL CHECK(snapshot_sha256 ~ '^[a-f0-9]{64}$'),
 created_by uuid NOT NULL REFERENCES qf.operator(id) ON UPDATE RESTRICT ON DELETE RESTRICT,created_at timestamptz NOT NULL,
 CONSTRAINT internal_play_capacity UNIQUE(product_id,slot),CONSTRAINT internal_play_operation UNIQUE(product_id,operation_key),
 CONSTRAINT internal_play_snapshot UNIQUE(product_id,snapshot_sha256),CONSTRAINT internal_play_exact UNIQUE(id,product_id,snapshot_sha256),
 CONSTRAINT internal_play_parent FOREIGN KEY(parent_version_id,product_id,parent_snapshot_sha256) REFERENCES qf.product_version(id,product_id,snapshot_sha256) ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE TABLE qf.access_key (
 id uuid PRIMARY KEY,product_id varchar(80) NOT NULL,play_version_id uuid NOT NULL,play_snapshot_sha256 char(64) NOT NULL,
 credential_digest char(64) NOT NULL UNIQUE CHECK(credential_digest ~ '^[a-f0-9]{64}$'),issue_operation_key uuid NOT NULL,
 issue_binding_text text NOT NULL,issue_binding_sha256 char(64) NOT NULL CHECK(issue_binding_sha256 ~ '^[a-f0-9]{64}$'),
 valid_for_seconds integer NOT NULL CHECK(valid_for_seconds BETWEEN 3600 AND 2592000),
 issued_by uuid NOT NULL REFERENCES qf.operator(id) ON UPDATE RESTRICT ON DELETE RESTRICT,issued_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,
 revoked_at timestamptz,void_operation_key uuid,void_binding_text text,void_binding_sha256 char(64),voided_by uuid REFERENCES qf.operator(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
 CONSTRAINT access_key_issue_operation UNIQUE(product_id,issue_operation_key),CONSTRAINT access_key_void_operation UNIQUE(product_id,void_operation_key),
 CONSTRAINT access_key_exact UNIQUE(id,product_id,play_version_id,play_snapshot_sha256),
 CONSTRAINT access_key_play FOREIGN KEY(play_version_id,product_id,play_snapshot_sha256) REFERENCES qf.internal_play_version(id,product_id,snapshot_sha256) ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE TABLE qf.consumer_session (
 id uuid PRIMARY KEY,key_id uuid NOT NULL UNIQUE,product_id varchar(80) NOT NULL,play_version_id uuid NOT NULL,play_snapshot_sha256 char(64) NOT NULL,created_at timestamptz NOT NULL,
 state_revision integer NOT NULL CHECK(state_revision BETWEEN 0 AND 2147483647),answers_text text NOT NULL,consumer_state_answers_sha256 char(64) NOT NULL,
 progress_text text NOT NULL,progress_sha256 char(64) NOT NULL,last_binding_text text,last_binding_sha256 char(64),last_receipt_text text,last_receipt_sha256 char(64),
 CONSTRAINT consumer_session_key FOREIGN KEY(key_id,product_id,play_version_id,play_snapshot_sha256) REFERENCES qf.access_key(id,product_id,play_version_id,play_snapshot_sha256) ON UPDATE RESTRICT ON DELETE RESTRICT,
 CONSTRAINT consumer_session_claim UNIQUE(key_id,id),
 CONSTRAINT consumer_session_final UNIQUE(id,key_id,product_id,play_version_id,play_snapshot_sha256,state_revision,consumer_state_answers_sha256,progress_sha256)
);
CREATE TABLE qf.consumer_grant (
 key_id uuid NOT NULL,slot smallint NOT NULL CHECK(slot BETWEEN 1 AND 16),session_id uuid NOT NULL,
 grant_id uuid NOT NULL UNIQUE,credential_digest char(64) NOT NULL UNIQUE CHECK(credential_digest ~ '^[a-f0-9]{64}$'),
 issued_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,
 PRIMARY KEY(key_id,slot),CONSTRAINT consumer_grant_session FOREIGN KEY(key_id,session_id) REFERENCES qf.consumer_session(key_id,id) ON UPDATE RESTRICT ON DELETE RESTRICT,
 CONSTRAINT consumer_grant_times CHECK((qf.consumer_moment(issued_at) IS NOT NULL AND qf.consumer_moment(expires_at) IS NOT NULL AND expires_at=issued_at+interval '8 hours' AND (revoked_at IS NULL OR (qf.consumer_moment(revoked_at) IS NOT NULL AND revoked_at>=issued_at))) IS TRUE)
);
CREATE TABLE qf.quiz_report (
 id uuid PRIMARY KEY,key_id uuid NOT NULL UNIQUE,session_id uuid NOT NULL UNIQUE,product_id varchar(80) NOT NULL,play_version_id uuid NOT NULL,play_snapshot_sha256 char(64) NOT NULL,
 state_revision integer NOT NULL,consumer_state_answers_sha256 char(64) NOT NULL,progress_sha256 char(64) NOT NULL,completion_key uuid NOT NULL,
 binding_text text NOT NULL,binding_sha256 char(64) NOT NULL,snapshot_text text NOT NULL,snapshot_sha256 char(64) NOT NULL,display_sha256 char(64) NOT NULL,completed_at timestamptz NOT NULL,
 CONSTRAINT quiz_report_operation UNIQUE(session_id,completion_key),
 CONSTRAINT quiz_report_session_final FOREIGN KEY(session_id,key_id,product_id,play_version_id,play_snapshot_sha256,state_revision,consumer_state_answers_sha256,progress_sha256)
 REFERENCES qf.consumer_session(id,key_id,product_id,play_version_id,play_snapshot_sha256,state_revision,consumer_state_answers_sha256,progress_sha256) ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE TABLE qf.consumer_exchange_budget (
 singleton boolean PRIMARY KEY CHECK(singleton IS TRUE),window_index bigint NOT NULL CHECK(window_index>=0),used smallint NOT NULL CHECK(used BETWEEN 0 AND 60)
);
INSERT INTO qf.consumer_exchange_budget VALUES(true,floor(extract(epoch FROM clock_timestamp())/60)::bigint,0);

CREATE FUNCTION qf.consumer_play_valid(r qf.internal_play_version) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE b jsonb; s jsonb;
BEGIN
 IF qf.consumer_body_valid(r.binding_text,'play_binding',8192) IS NOT TRUE OR qf.consumer_body_valid(r.snapshot_text,'play',65536) IS NOT TRUE THEN RETURN false; END IF;
 b:=r.binding_text::jsonb;s:=r.snapshot_text::jsonb;
 RETURN (r.binding_sha256::text=qf.sha256_utf8(r.binding_text) AND r.snapshot_sha256::text=qf.sha256_utf8(r.snapshot_text) AND qf.consumer_moment(r.created_at) IS NOT NULL
 AND b->>'operationKey'=r.operation_key::text AND b->'parent'=jsonb_build_object('productId',r.product_id,'versionId',r.parent_version_id,'snapshotSha256',r.parent_snapshot_sha256::text)
 AND b->'parent'=s->'parent' AND b->'renderer'=s->'renderer' AND s->>'mappingSha256'=qf.sha256_utf8(qf.consumer_canonical(s->'mapping'))
 AND s->'parentSnapshot'->>'productId'=r.product_id AND s->'resources'->>'productId'=r.product_id
 AND NOT EXISTS(SELECT 1 FROM jsonb_each(s->'mapping'->'states') a WHERE a.value->'source' IS DISTINCT FROM s->'parentSnapshot'->'components'->a.key)) IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
ALTER TABLE qf.internal_play_version ADD CONSTRAINT internal_play_text_exact CHECK(qf.consumer_play_valid(internal_play_version) IS TRUE);

CREATE FUNCTION qf.consumer_key_valid(r qf.access_key) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE b jsonb; v jsonb; empty_void boolean; full_void boolean;
BEGIN
 empty_void:=r.revoked_at IS NULL AND r.void_operation_key IS NULL AND r.void_binding_text IS NULL AND r.void_binding_sha256 IS NULL AND r.voided_by IS NULL;
 full_void:=r.revoked_at IS NOT NULL AND r.void_operation_key IS NOT NULL AND r.void_binding_text IS NOT NULL AND r.void_binding_sha256 IS NOT NULL AND r.voided_by IS NOT NULL;
 IF NOT(empty_void OR full_void) OR qf.consumer_body_valid(r.issue_binding_text,'issue',4096) IS NOT TRUE THEN RETURN false; END IF;
 b:=r.issue_binding_text::jsonb;
 IF full_void THEN
  IF qf.consumer_body_valid(r.void_binding_text,'void',4096) IS NOT TRUE THEN RETURN false; END IF;
  v:=r.void_binding_text::jsonb;
  IF (v=jsonb_build_object('schemaVersion','quizforge.access-key-void-unused.v1','productId',r.product_id,'operationKey',r.void_operation_key,'keyId',r.id,'issueBindingSha256',r.issue_binding_sha256::text)
   AND r.void_binding_sha256::text=qf.sha256_utf8(r.void_binding_text) AND qf.consumer_moment(r.revoked_at) IS NOT NULL AND r.revoked_at>=r.issued_at) IS NOT TRUE THEN RETURN false; END IF;
 END IF;
 RETURN (b=jsonb_build_object('schemaVersion','quizforge.access-key-issue.v1','operationKey',r.issue_operation_key,'keyId',r.id,'play',jsonb_build_object('productId',r.product_id,'playVersionId',r.play_version_id,'playSnapshotSha256',r.play_snapshot_sha256::text),'credentialDigest',r.credential_digest::text,'validForSeconds',r.valid_for_seconds)
 AND r.issue_binding_sha256::text=qf.sha256_utf8(r.issue_binding_text) AND qf.consumer_moment(r.issued_at) IS NOT NULL AND qf.consumer_moment(r.expires_at) IS NOT NULL AND r.expires_at=r.issued_at+r.valid_for_seconds*interval '1 second') IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
ALTER TABLE qf.access_key ADD CONSTRAINT access_key_text_exact CHECK(qf.consumer_key_valid(access_key) IS TRUE);

CREATE FUNCTION qf.consumer_session_valid(r qf.consumer_session) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE a jsonb; p jsonb; b jsonb; receipt jsonb; ref jsonb;
BEGIN
 IF qf.consumer_body_valid(r.answers_text,'answers',65536) IS NOT TRUE OR qf.consumer_body_valid(r.progress_text,'progress',4096) IS NOT TRUE THEN RETURN false; END IF;
 a:=r.answers_text::jsonb;p:=r.progress_text::jsonb;
 IF (r.consumer_state_answers_sha256::text=qf.sha256_utf8(r.answers_text) AND r.progress_sha256::text=qf.sha256_utf8(r.progress_text) AND qf.consumer_moment(r.created_at) IS NOT NULL) IS NOT TRUE THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM (SELECT value->>'questionId' q,lag(value->>'questionId') OVER(ORDER BY ordinal) prev FROM jsonb_array_elements(a->'answers') WITH ORDINALITY t(value,ordinal)) t WHERE prev COLLATE "C">=q COLLATE "C") THEN RETURN false; END IF;
 IF r.state_revision=0 THEN RETURN (a->'answers'='[]'::jsonb AND p->'progress'=jsonb_build_object('questionId',NULL) AND r.last_binding_text IS NULL AND r.last_binding_sha256 IS NULL AND r.last_receipt_text IS NULL AND r.last_receipt_sha256 IS NULL) IS TRUE; END IF;
 IF r.last_binding_text IS NULL OR r.last_binding_sha256 IS NULL OR r.last_receipt_text IS NULL OR r.last_receipt_sha256 IS NULL OR qf.consumer_body_valid(r.last_binding_text,'save',4096) IS NOT TRUE OR qf.consumer_body_valid(r.last_receipt_text,'save_receipt',8192) IS NOT TRUE THEN RETURN false; END IF;
 b:=r.last_binding_text::jsonb;receipt:=r.last_receipt_text::jsonb;
 ref:=jsonb_build_object('productId',r.product_id,'playVersionId',r.play_version_id,'playSnapshotSha256',r.play_snapshot_sha256::text,'keyId',r.key_id,'sessionId',r.id);
 RETURN (r.last_binding_sha256::text=qf.sha256_utf8(r.last_binding_text) AND r.last_receipt_sha256::text=qf.sha256_utf8(r.last_receipt_text)
 AND b=jsonb_build_object('schemaVersion','quizforge.consumer-save.v1','session',ref,'expectedStateRevision',r.state_revision-1,'consumerStateAnswersSha256',r.consumer_state_answers_sha256::text,'progressSha256',r.progress_sha256::text)
 AND receipt->'binding'=b AND receipt->>'bindingSha256'=r.last_binding_sha256::text AND receipt->'appliedStateRevision'=to_jsonb(r.state_revision)) IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
ALTER TABLE qf.consumer_session ADD CONSTRAINT consumer_session_text_exact CHECK(qf.consumer_session_valid(consumer_session) IS TRUE);

CREATE FUNCTION qf.consumer_report_valid(r qf.quiz_report) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE b jsonb; s jsonb; v jsonb; ref jsonb;
BEGIN
 IF qf.consumer_body_valid(r.binding_text,'complete',4096) IS NOT TRUE OR qf.consumer_body_valid(r.snapshot_text,'report',524288) IS NOT TRUE THEN RETURN false; END IF;
 b:=r.binding_text::jsonb;s:=r.snapshot_text::jsonb;v:=s->'view';
 ref:=jsonb_build_object('productId',r.product_id,'playVersionId',r.play_version_id,'playSnapshotSha256',r.play_snapshot_sha256::text,'keyId',r.key_id,'sessionId',r.session_id);
 RETURN (r.binding_sha256::text=qf.sha256_utf8(r.binding_text) AND r.snapshot_sha256::text=qf.sha256_utf8(r.snapshot_text) AND r.display_sha256::text=qf.sha256_utf8(qf.consumer_canonical(v))
 AND qf.consumer_moment(r.completed_at) IS NOT NULL
 AND b=jsonb_build_object('schemaVersion','quizforge.consumer-complete.v1','session',ref,'expectedStateRevision',r.state_revision,'consumerStateAnswersSha256',r.consumer_state_answers_sha256::text,'progressSha256',r.progress_sha256::text,'completionKey',r.completion_key)
 AND s->'binding'=b AND v->'session'=ref AND v->>'reportId'=r.id::text AND v->>'completedAt'=qf.consumer_moment(r.completed_at) AND v->>'completionBindingSha256'=r.binding_sha256::text
 AND qf.sha256_utf8(qf.consumer_canonical(jsonb_build_object('schemaVersion','quizforge.consumer-state-answers.v1','answers',s->'answers')))=r.consumer_state_answers_sha256::text
 AND qf.sha256_utf8(qf.consumer_canonical(jsonb_build_object('schemaVersion','quizforge.consumer-state-progress.v1','progress',s->'progress')))=r.progress_sha256::text
 AND s->'score'->'score'->>'answersHash'=v->'display'->>'answersHash' AND s->'score'->'score'->>'logicHash'=v->'display'->>'logicHash'
 AND s->'score'->'score'->'decision'->'selectedResultRef'=v->'display'->'selectedResultRef' AND s->'score'->'reportTemplateRef'=v->'display'->'reportTemplateRef') IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
ALTER TABLE qf.quiz_report ADD CONSTRAINT quiz_report_text_exact CHECK(qf.consumer_report_valid(quiz_report) IS TRUE);

CREATE FUNCTION qf.protect_consumer_play() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE parent qf.product_version; source qf.draft_revision; s jsonb; archived timestamptz; head integer;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'IMMUTABLE_CONSUMER_PLAY' USING ERRCODE='23514'; END IF;
 IF NOT pg_try_advisory_xact_lock_shared(72461,2) THEN RAISE EXCEPTION 'CONSUMER_MAINTENANCE_BUSY' USING ERRCODE='55P03'; END IF;
 SELECT archived_at INTO archived FROM qf.product WHERE id=NEW.product_id FOR UPDATE;
 IF NOT FOUND OR archived IS NOT NULL THEN RAISE EXCEPTION 'CONSUMER_PRODUCT_INACTIVE' USING ERRCODE='23514'; END IF;
 SELECT * INTO parent FROM qf.product_version WHERE id=NEW.parent_version_id AND product_id=NEW.product_id AND snapshot_sha256=NEW.parent_snapshot_sha256;
 IF NOT FOUND THEN RAISE EXCEPTION 'CONSUMER_PARENT_MISSING' USING ERRCODE='23514'; END IF;
 SELECT current_revision INTO head FROM qf.product_draft WHERE product_id=parent.product_id AND id=parent.draft_id;
 IF head IS DISTINCT FROM parent.revision THEN RAISE EXCEPTION 'CONSUMER_PARENT_OBSOLETE' USING ERRCODE='23514'; END IF;
 SELECT * INTO source FROM qf.draft_revision WHERE product_id=parent.product_id AND draft_id=parent.draft_id AND revision=parent.revision;
 s:=NEW.snapshot_text::jsonb;
 IF qf.consumer_canonical(s->'parentSnapshot') IS DISTINCT FROM parent.snapshot_text OR qf.consumer_canonical(s->'resources') IS DISTINCT FROM source.asset_set_text THEN RAISE EXCEPTION 'CONSUMER_PARENT_MISMATCH' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER internal_play_source BEFORE INSERT OR UPDATE ON qf.internal_play_version FOR EACH ROW EXECUTE FUNCTION qf.protect_consumer_play();

CREATE FUNCTION qf.protect_consumer_key() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE archived timestamptz;
BEGIN
 IF NOT pg_try_advisory_xact_lock_shared(72461,2) THEN RAISE EXCEPTION 'CONSUMER_MAINTENANCE_BUSY' USING ERRCODE='55P03'; END IF;
 IF TG_OP='INSERT' THEN
  SELECT archived_at INTO archived FROM qf.product WHERE id=NEW.product_id FOR UPDATE;
  IF NOT FOUND OR archived IS NOT NULL OR NEW.revoked_at IS NOT NULL OR NEW.void_operation_key IS NOT NULL OR NEW.void_binding_text IS NOT NULL OR NEW.void_binding_sha256 IS NOT NULL OR NEW.voided_by IS NOT NULL THEN RAISE EXCEPTION 'CONSUMER_INVALID_ISSUE' USING ERRCODE='23514'; END IF;
  NEW.issued_at:=date_trunc('milliseconds',clock_timestamp());NEW.expires_at:=NEW.issued_at+NEW.valid_for_seconds*interval '1 second';
 ELSE
  IF (to_jsonb(NEW)-ARRAY['revoked_at','void_operation_key','void_binding_text','void_binding_sha256','voided_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['revoked_at','void_operation_key','void_binding_text','void_binding_sha256','voided_by']) OR OLD.revoked_at IS NOT NULL OR NEW.revoked_at IS NULL THEN RAISE EXCEPTION 'IMMUTABLE_CONSUMER_ISSUE' USING ERRCODE='23514'; END IF;
  -- UPDATE already holds this Key's row lock. Session INSERT takes the same Key lock before checking void.
  IF EXISTS(SELECT 1 FROM qf.consumer_session WHERE key_id=OLD.id) OR EXISTS(SELECT 1 FROM qf.quiz_report WHERE key_id=OLD.id) THEN RAISE EXCEPTION 'CONSUMER_KEY_CLAIMED' USING ERRCODE='23514'; END IF;
  NEW.revoked_at:=date_trunc('milliseconds',clock_timestamp());
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER consumer_key_change BEFORE INSERT OR UPDATE ON qf.access_key FOR EACH ROW EXECUTE FUNCTION qf.protect_consumer_key();

CREATE FUNCTION qf.protect_consumer_session() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE k qf.access_key; source jsonb; progress jsonb;
BEGIN
 IF NOT pg_try_advisory_xact_lock_shared(72461,2) THEN RAISE EXCEPTION 'CONSUMER_MAINTENANCE_BUSY' USING ERRCODE='55P03'; END IF;
 SELECT * INTO k FROM qf.access_key WHERE id=NEW.key_id FOR UPDATE;
 IF NOT FOUND OR k.revoked_at IS NOT NULL OR k.void_operation_key IS NOT NULL OR k.void_binding_text IS NOT NULL OR k.void_binding_sha256 IS NOT NULL OR k.voided_by IS NOT NULL THEN RAISE EXCEPTION 'CONSUMER_KEY_VOID' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state_revision<>0 OR k.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'CONSUMER_INVALID_CLAIM' USING ERRCODE='23514'; END IF;
 ELSE
  IF ROW(NEW.id,NEW.key_id,NEW.product_id,NEW.play_version_id,NEW.play_snapshot_sha256,NEW.created_at) IS DISTINCT FROM ROW(OLD.id,OLD.key_id,OLD.product_id,OLD.play_version_id,OLD.play_snapshot_sha256,OLD.created_at) OR NEW.state_revision::bigint<>OLD.state_revision::bigint+1 THEN RAISE EXCEPTION 'CONSUMER_INVALID_REVISION' USING ERRCODE='23514'; END IF;
 END IF;
 SELECT d.canonical_content_text::jsonb INTO source FROM qf.internal_play_version p JOIN qf.product_version v ON(v.id,v.product_id,v.snapshot_sha256)=(p.parent_version_id,p.product_id,p.parent_snapshot_sha256) JOIN qf.draft_revision d ON(d.product_id,d.draft_id,d.revision)=(v.product_id,v.draft_id,v.revision) WHERE p.id=NEW.play_version_id AND p.product_id=NEW.product_id AND p.snapshot_sha256=NEW.play_snapshot_sha256;
 IF NOT FOUND THEN RAISE EXCEPTION 'CONSUMER_SOURCE_MISSING' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.answers_text::jsonb->'answers') a WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(source->'questions') q CROSS JOIN LATERAL jsonb_array_elements(q->'options') o WHERE q->>'id'=a->>'questionId' AND o->>'id'=a->>'optionId')) THEN RAISE EXCEPTION 'CONSUMER_INVALID_ANSWER' USING ERRCODE='23514'; END IF;
 progress:=NEW.progress_text::jsonb->'progress'->'questionId';
 IF progress IS DISTINCT FROM 'null'::jsonb AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(source->'questions') q WHERE q->'id'=progress) THEN RAISE EXCEPTION 'CONSUMER_INVALID_PROGRESS' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER consumer_session_change BEFORE INSERT OR UPDATE ON qf.consumer_session FOR EACH ROW EXECUTE FUNCTION qf.protect_consumer_session();

CREATE FUNCTION qf.protect_consumer_grant() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE k qf.access_key; selected integer; at timestamptz;
BEGIN
 IF NOT pg_try_advisory_xact_lock_shared(72461,2) THEN RAISE EXCEPTION 'CONSUMER_MAINTENANCE_BUSY' USING ERRCODE='55P03'; END IF;
 SELECT * INTO k FROM qf.access_key WHERE id=NEW.key_id FOR UPDATE;
 IF NOT FOUND OR k.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'CONSUMER_KEY_VOID' USING ERRCODE='23514'; END IF;
 at:=date_trunc('milliseconds',clock_timestamp());
 IF TG_OP='UPDATE' AND ROW(NEW.key_id,NEW.slot,NEW.session_id) IS DISTINCT FROM ROW(OLD.key_id,OLD.slot,OLD.session_id) THEN RAISE EXCEPTION 'IMMUTABLE_GRANT_SCOPE' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.grant_id,NEW.credential_digest,NEW.issued_at,NEW.expires_at) IS NOT DISTINCT FROM ROW(OLD.grant_id,OLD.credential_digest,OLD.issued_at,OLD.expires_at) THEN
  IF OLD.revoked_at IS NOT NULL OR NEW.revoked_at IS NULL THEN RAISE EXCEPTION 'IMMUTABLE_GRANT_LOGOUT' USING ERRCODE='23514'; END IF;
  NEW.revoked_at:=at; RETURN NEW;
 END IF;
 IF k.expires_at<=at AND NOT EXISTS(SELECT 1 FROM qf.quiz_report WHERE key_id=k.id) THEN RAISE EXCEPTION 'CONSUMER_KEY_EXPIRED' USING ERRCODE='23514'; END IF;
 SELECT slot INTO selected FROM qf.consumer_grant WHERE key_id=NEW.key_id AND (revoked_at IS NOT NULL OR expires_at<=at) ORDER BY slot LIMIT 1;
 IF selected IS NULL THEN SELECT n INTO selected FROM generate_series(1,16) n WHERE NOT EXISTS(SELECT 1 FROM qf.consumer_grant g WHERE g.key_id=NEW.key_id AND g.slot=n) ORDER BY n LIMIT 1; END IF;
 IF selected IS NULL THEN SELECT slot INTO selected FROM qf.consumer_grant WHERE key_id=NEW.key_id ORDER BY issued_at,slot LIMIT 1; END IF;
 IF NEW.slot IS DISTINCT FROM selected OR NEW.revoked_at IS NOT NULL OR (TG_OP='UPDATE' AND (NEW.grant_id=OLD.grant_id OR NEW.credential_digest=OLD.credential_digest)) THEN RAISE EXCEPTION 'CONSUMER_GRANT_ROTATION' USING ERRCODE='23514'; END IF;
 NEW.issued_at:=at;NEW.expires_at:=at+interval '8 hours';RETURN NEW;
END $$;
CREATE TRIGGER consumer_grant_change BEFORE INSERT OR UPDATE ON qf.consumer_grant FOR EACH ROW EXECUTE FUNCTION qf.protect_consumer_grant();

CREATE FUNCTION qf.protect_consumer_report() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE p qf.internal_play_version; s qf.consumer_session; body jsonb; expected jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'IMMUTABLE_CONSUMER_REPORT' USING ERRCODE='23514'; END IF;
 IF NOT pg_try_advisory_xact_lock_shared(72461,2) THEN RAISE EXCEPTION 'CONSUMER_MAINTENANCE_BUSY' USING ERRCODE='55P03'; END IF;
 PERFORM 1 FROM qf.access_key WHERE id=NEW.key_id FOR UPDATE;
 SELECT * INTO s FROM qf.consumer_session WHERE id=NEW.session_id AND key_id=NEW.key_id FOR UPDATE;
 SELECT * INTO p FROM qf.internal_play_version WHERE id=NEW.play_version_id AND product_id=NEW.product_id AND snapshot_sha256=NEW.play_snapshot_sha256;
 IF s.id IS NULL OR p.id IS NULL THEN RAISE EXCEPTION 'CONSUMER_REPORT_SOURCE_MISSING' USING ERRCODE='23514'; END IF;
 expected:=jsonb_build_object('schemaVersion','quizforge.internal-play-receipt.v1','id',p.id,'slot',p.slot,'binding',p.binding_text::jsonb,'bindingSha256',p.binding_sha256::text,'snapshotSha256',p.snapshot_sha256::text,'createdBy',p.created_by,'createdAt',qf.consumer_moment(p.created_at),'purpose','internal-test','publicationApproved',false);
 body:=NEW.snapshot_text::jsonb;
 IF body->'play' IS DISTINCT FROM jsonb_build_object('play',expected,'snapshot',p.snapshot_text::jsonb) OR body->'answers' IS DISTINCT FROM s.answers_text::jsonb->'answers' OR body->'progress' IS DISTINCT FROM s.progress_text::jsonb->'progress' THEN RAISE EXCEPTION 'CONSUMER_REPORT_SOURCE_MISMATCH' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER consumer_report_source BEFORE INSERT OR UPDATE ON qf.quiz_report FOR EACH ROW EXECUTE FUNCTION qf.protect_consumer_report();

CREATE FUNCTION qf.protect_consumer_budget() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE current_window bigint;
BEGIN
 current_window:=floor(extract(epoch FROM clock_timestamp())/60)::bigint;
 IF NEW.singleton IS DISTINCT FROM true OR NEW.singleton IS DISTINCT FROM OLD.singleton OR OLD.window_index>current_window OR NEW.window_index<>current_window OR NOT((NEW.window_index=OLD.window_index AND NEW.used=OLD.used+1) OR (NEW.window_index>OLD.window_index AND NEW.used=1)) THEN RAISE EXCEPTION 'CONSUMER_BUDGET_CHANGE' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER consumer_budget_change BEFORE UPDATE ON qf.consumer_exchange_budget FOR EACH ROW EXECUTE FUNCTION qf.protect_consumer_budget();

REVOKE ALL ON qf.internal_play_version,qf.access_key,qf.consumer_session,qf.consumer_grant,qf.quiz_report,qf.consumer_exchange_budget FROM PUBLIC;
REVOKE ALL ON FUNCTION qf.consumer_schema(text),qf.consumer_canonical(jsonb),qf.consumer_json_valid(jsonb,jsonb,integer),qf.consumer_body_valid(text,text,integer),qf.consumer_moment(timestamptz),qf.consumer_play_valid(qf.internal_play_version),qf.consumer_key_valid(qf.access_key),qf.consumer_session_valid(qf.consumer_session),qf.consumer_report_valid(qf.quiz_report),qf.protect_consumer_play(),qf.protect_consumer_key(),qf.protect_consumer_session(),qf.protect_consumer_grant(),qf.protect_consumer_report(),qf.protect_consumer_budget() FROM PUBLIC;

-- New labels are compared as text until this transaction commits. Existing targets remain byte-for-byte semantically preserved.
ALTER TYPE qf.audit_action ADD VALUE 'internal_play_created';
ALTER TYPE qf.audit_action ADD VALUE 'access_key_issued';
